/**
 * @ingroup iface_xx_input_method_manager_v2
 * @struct xx_input_method_manager_v2_interface
 */
struct xx_input_method_manager_v2_interface {
	/**
	 * request an input method object
	 *
	 * Request a new input xx_input_method_v1 object associated with
	 * a given seat.
	 */
	void (*get_input_method)(struct wl_client *client,
				 struct wl_resource *resource,
				 struct wl_resource *seat,
				 uint32_t input_method);
	/**
	 * create a positioner object
	 *
	 * Create a positioner object. A positioner object is used to
	 * position surfaces relative to some parent surface. See the
	 * interface description and xdg_surface.get_popup for details.
	 */
	void (*get_positioner)(struct wl_client *client,
			       struct wl_resource *resource,
			       uint32_t id);
	/**
	 * destroy the input method manager
	 *
	 * Destroys the xx_input_method_manager_v2 object.
	 *
	 * The xx_input_method_v1 objects originating from it remain valid.
	 */
	void (*destroy)(struct wl_client *client,
			struct wl_resource *resource);
};


